    fn move_backward_tabs(&mut self, count: u16) {
        trace!("Moving backward {} tabs", count);

        let old_col = self.grid.cursor.point.column.0;
        for _ in 0..count {
            let mut col = self.grid.cursor.point.column;

            if col == 0 {
                break;
